CREATE COLUMN TABLE "TEST_AP"."OPCM" ("AbsEntry" INTEGER CS_INT NOT NULL , "IdCode" NVARCHAR(50) NOT NULL , "PosCode" NVARCHAR(6) NOT NULL , "PosDesc" NVARCHAR(100), "CrCode" NVARCHAR(20) NOT NULL , "CrDesc" NVARCHAR(100), "Remarks" NVARCHAR(250), PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OPCM_ID_CODE" ON "TEST_AP"."OPCM" ( "IdCode" ASC );
CREATE UNIQUE INDEX "OPCM_POC_CR" ON "TEST_AP"."OPCM" ( "PosCode" ASC, "CrCode" ASC )